using Microsoft.EntityFrameworkCore;
using PeopleHub.Infrastructure.Persistence;
using PeopleHub.Application.Common;
using PeopleHub.Application.Modules.Talent;
using PeopleHub.Domain.Entities;
namespace PeopleHub.Tests;
public class PerformanceResponseTests
{
 class User(int employee=6,bool hr=false):ICurrentUser{public string Email=>$"response{employee}@example.local";public int? EmployeeId=>employee;public int UserId=>employee;public bool IsAuthenticated=>true;public bool IsInRole(string r)=>hr;public bool Can(string p)=>hr;}
 static async Task<AppDbContext> Db(){var d=new AppDbContext(new DbContextOptionsBuilder<AppDbContext>().UseSqlite("Data Source=:memory:").Options);await d.Database.OpenConnectionAsync();await d.Database.MigrateAsync();await SeedData.InitializeAsync(d,"Admin123!","Demo123!",new DateTime(2026,11,24));return d;}
 static PerfService S(AppDbContext d,User? u=null){u??=new();var c=new AppClock(TimeProvider.System);var a=new AuditService(d,u,c);return new(d,u,new AccessScope(d,u),c,a,new NotificationService(d,u,c));}
 static async Task<int> Setup(AppDbContext d,CycleStatus status=CycleStatus.Closed){var c=new PerfCycle{Name="Response test",Start=new(2026,1,1),End=new(2026,10,31),Status=status};d.Add(c);await d.SaveAsync();var a=new PerfAppraisal{CycleId=c.Id,EmployeeId=6,ManagerDone=true,ManagerScore=4,FinalScore=4};d.Add(a);await d.SaveAsync();return a.Id;}
 [Fact]public async Task AcknowledgementAndAppealAreIndependentAndNeverChangeScore(){await using var d=await Db();int id=await Setup(d);await S(d).RespondAsync(id,"Acknowledged","Received, not agreement");await S(d).RespondAsync(id,"Appeal","Evidence disputed");Assert.Equal(2,(await S(d).ResponsesAsync(id)).Count);Assert.Equal(4,(await d.Set<PerfAppraisal>().FindAsync(id))!.FinalScore);await Assert.ThrowsAsync<DomainException>(()=>S(d).RespondAsync(id,"Appeal","Again"));}
 [Fact]public async Task OnlyOwnerCanRespondAfterClosureWithReason(){await using var d=await Db();int id=await Setup(d,CycleStatus.Open);await Assert.ThrowsAsync<DomainException>(()=>S(d).RespondAsync(id,"Appeal","Early"));var appraisal=(await d.Set<PerfAppraisal>().FindAsync(id))!;appraisal.Cycle!.Status=CycleStatus.Closed;await d.SaveAsync();await Assert.ThrowsAsync<DomainException>(()=>S(d,new(1,true)).RespondAsync(id,"Acknowledged","Not owner"));await Assert.ThrowsAsync<DomainException>(()=>S(d).RespondAsync(id,"Appeal",""));await Assert.ThrowsAsync<DomainException>(()=>S(d,new(7)).ResponsesAsync(id));}
 [Fact]public async Task IndependentHrDecisionReferencesAppealWithoutRewritingResult(){await using var d=await Db();int id=await Setup(d);await S(d).RespondAsync(id,"Appeal","Review evidence");int appeal=(await d.Set<PerformanceResponse>().SingleAsync()).Id;await Assert.ThrowsAsync<DomainException>(()=>S(d,new(6,true)).DecideAppealAsync(id,appeal,"Upheld","Self review"));await Assert.ThrowsAsync<DomainException>(()=>S(d,new(7)).DecideAppealAsync(id,appeal,"Upheld","No grant"));await S(d,new(1,true)).DecideAppealAsync(id,appeal,"ChangeRecommended","Correction review required");Assert.Equal(4,(await d.Set<PerfAppraisal>().FindAsync(id))!.FinalScore);var response=await d.Set<PerformanceResponse>().SingleAsync(x=>x.AppealId==appeal);Assert.Equal("ChangeRecommended",response.Kind);await Assert.ThrowsAsync<DomainException>(()=>S(d,new(1,true)).DecideAppealAsync(id,appeal,"Upheld","Again"));}
 [Fact]public async Task ResponsesAreAppendOnly(){await using var d=await Db();int id=await Setup(d);await S(d).RespondAsync(id,"Acknowledged","Receipt");var x=await d.Set<PerformanceResponse>().SingleAsync();x.Note="Rewrite";await Assert.ThrowsAsync<InvalidOperationException>(()=>d.SaveAsync());}
}
